function about(){open('三大梗宇宙 · V13 镜面宇宙',`<div class="about"><p>英雄联盟只有一个综合板块：S赛、经典热梗、对线小技巧和大乱斗一起随机出题。题面尽量用日常话，常见梗和小技巧会有简单解释。</p><p>篮球梦之队围绕球场日常、球星与解说梗；抽象热梗围绕带文学、旅行、饭点和互联网嘴替。</p><p>共 ${D.counts.questions} 道题、${D.counts.parodyCards} 张自制海克斯、${D.counts.people} 位人物角色。8 / 16 / 24 题随机；联盟按连续四幕抽取，其余主题兼顾六个维度。</p><p>点选后自动进入下一题，不需要重复确认。误选可以返回上一题改选。作答触发卡需要相关题中的实际选择；人物自带赠卡单独展示，不生成作答证据。</p><p>人物倾向和剧情是娱乐创作。${window.WORLD_SOURCES.filter(p=>p.verifiedReference).length} 位头像已按公开照片重绘；其余核对中人物使用文字占位。摇摆导演是本作原创虚构角色。所有卡牌效果都是自制恶搞。</p><p>热梗为截至 ${D.editorial.checkedAt} 整理的本期快照，来源与说明可查看。全部运行图片、题库和页面已内置，答案只留本机。</p><button class="secondary" data-action="trend-note">本期热梗出处 ↗</button><button class="secondary" data-action="download-html">下载完整离线网页 ↓</button></div>`);}
function questionArt(q){if(q.theme!=='lol')return '';const map={'collector':'collector-union','collector-audit':'collector-union','double-laugh':'double-laugh','tes-top':'tes-top','flash-wall':'flash-wall','golden-time':'double-zhonya','six-swords':'six-infinity','brush':'brush-five','snowball-return':'snowball-hearse'};const a=findCard(map[q.chapter]);return a?`<div class="question-equipment">${perkIcon(a)}<span>${esc(a.visual?a.visual.label:a.name)}<small>场景配图 / 恶搞效果另算</small></span></div>`:'';}
function memeScenes(){return `<section class="meme-scene-section"><img class="meme-banner" src="${window.WORLD_MEME_BANNER}" alt="参考收集者、无尽、帽子和金身图标重绘的装备梗插画"><div class="section-head"><h2>名场面，换你来接。</h2><span>梗有出处 / 情境改编</span></div><div class="meme-scenes">${D.memeReferences.map(m=>`<button data-action="meme" data-id="${m.id}">${portrait(person('lol-'+m.personId))}<strong>${esc(m.title)}</strong><small>联盟综合 · 四幕情境 ↗</small></button>`).join('')}</div></section>`;}
function showMeme(id){const m=D.memeReferences.find(m=>m.id===id);if(!m)return;open(m.title+' · 名场面改编',`<div class="meme-note">${perkIcon(findCard(m.card))}<p>${esc(m.description)}</p><p class="micro">参考：${esc(m.sourceTitle)}。人物反应和卡牌效果是本作娱乐创作。</p><a href="${esc(m.sourcePage)}" target="_blank" rel="noreferrer">查看梗出处（需联网） ↗</a><button class="primary full-width" data-action="meme-start" data-id="${m.id}">这次换我来接梗 · ${count} 题 →</button><p class="tiny">从这四幕开始，再随机加入联盟综合题库。正式计分。</p></div>`);}

function signatureList(p){const cards=(p.signaturePerks||[]).map(findCard).filter(Boolean);return cards.length?`<div class="signature-list"><small>这个人物的专属海克斯</small>${cards.slice(0,4).map(a=>`<button class="pill" data-action="peek" data-id="${a.id}">${esc(a.name)} ↗</button>`).join('')}</div>`:'';}
