function bondPanel(r){if(!r.bond)return '';const a=r.bond;return `<section class="bond-panel" data-bond="${a.id}"><div class="bond-art">${portrait(r.identity)}<span>×</span>${perkIcon(a)}</div><div><small>人物 × 专属海克斯 / 已激活</small><h2>${esc(r.identity.nickname||r.identity.name)} · ${esc(a.name)}</h2><p>${esc(a.punchline||a.line)}</p>${a.evidence[0]?`<p class="bond-evidence">来自你的选择：「${esc(a.evidence[0].choice)}」</p>`:''}<button class="text" data-action="card-note" data-id="${a.id}">看看这个人物怎么联动 ↗</button></div></section>`;}
function trendNote(){open('本期热梗 · 来源与整理日期',`<div class="about"><p>整理日期：${esc(D.editorial.checkedAt)}。${esc(D.editorial.note)}</p><p>舞蹈、翻唱、剪辑和自媒体题为本作改编情境。未复制原视频或音乐，也不把夸张卡牌效果当成真实机制。</p>${D.editorial.sources.map(s=>`<article class="trend-source"><a href="${esc(s.url)}" target="_blank" rel="noreferrer">${esc(s.title)} ↗</a><p>${esc(s.date||'2025—2026 整理')} / ${s.topics.map(esc).join('、')}</p></article>`).join('')}<p class="tiny">本版是离线可用的固定题库，后续可以按期增补。不是实时热榜排名。</p></div>`);}


