function intro(n=0){close();introStep=Math.max(0,Math.min(2,n));const titles=['镜子比你，晚笑了一秒。','原来，另一个你已经封神。','这一次，你来选择穿越。'],copy=['凌晨，你路过一面没见过的镜子。你停下，镜中的人却还在往前走——他转过身，把手伸向你。','镜面裂开三束光：一边是金色的冠军雨，一边是最后一投的聚光灯，还有一边，整个宇宙都在等你接梗。','把手放上去，跟着第一反应答题。门后会是谁？你会带着哪四个神人，把这一条时间线过得离谱又精彩？'];render(`<section class="intro-page narrow"><div class="intro-top"><span>穿越序章 / 0${introStep+1}</span><button class="text" data-action="intro-skip">跳过故事，直接穿越 ↗</button></div><div class="intro-art intro-panel-${introStep}" role="img" aria-label="${titles[introStep]}" style="background-image:url('${window.WORLD_BRANDING.intro}')"></div><div class="intro-copy"><span class="eyebrow">ANOTHER UNIVERSE IS CALLING</span><h1>${titles[introStep]}</h1><p>${copy[introStep]}</p><div class="intro-dots">${[0,1,2].map(i=>`<i class="${i===introStep?'on':''}"></i>`).join('')}</div><button class="primary full-width" data-action="intro-next">${introStep===2?'故事收好，选我的宇宙':'继续看下一幕'} ↗</button>${introStep?'<button class="text" data-action="intro-prev">← 上一幕</button>':''}</div></section>`);}

function storyArt(r){return r.identity.personId==='uzi'?`<figure class="ending-scene"><img src="${window.WORLD_BRANDING.uziEnding}" alt="架空S8漫画：污渍抱着奖杯落泪，金色的雨落下"><figcaption>平行 S8 / 架空漫画 · 非真实赛史</figcaption></figure>`:'';}
function reveal(record){close();currentRecord=JSON.parse(JSON.stringify(record));session=JSON.parse(JSON.stringify(record.session));theme=session.theme;count=session.count;result=analyzeRecord(record);const r=result,p=r.identity;render(`<section class="reveal-page narrow"><span class="eyebrow">穿越完成 / 档案已写入本机</span><h1>在这个宇宙，<br>你成为了 <em>${esc(p.nickname||p.name)}</em></h1><div class="reveal-scene ${p.personId==='uzi'?'is-uzi':'large-portrait-scene'}">${p.personId==='uzi'?`<img class="reveal-illustration" src="${window.WORLD_BRANDING.uziEnding}" alt="架空S8冠军结局，污渍抱杯落泪">`:`<img class="reveal-illustration" src="${window.WORLD_BRANDING[theme==='lol'?'revealLol':theme==='basket'?'revealBasket':'revealAbstract']}" alt="${esc(themed().name)}镜门身份背景"><div class="reveal-portrait">${portrait(p)}</div>`}<span class="scene-stamp">平行宇宙 / 架空剧情</span></div><div class="reveal-story"><h2>${esc(r.story[0])}</h2><p>${esc(r.story[1])}</p>${p.personId==='uzi'?'<blockquote>“世界第一 ADC！”<br><small>观众的欢呼和金色的雨，一起落在你的肩上。</small></blockquote>':''}${tags(p)}<button class="primary full-width" data-action="reveal-open">展开我的平行人生与五人战队 ↗</button><p class="micro">人物与剧情由本轮真实选择匹配 / 娱乐架空</p></div></section>`);}
function squadOpen(standalone=false){if(standalone){result=null;currentRecord=null;standaloneSquad=null;}const saved=read('squad.'+theme),valid=saved&&!E.squadError(saved.ids,theme,D,saved.free);squadDraft={ids:result?result.team.map(p=>p.id):valid?saved.ids.slice():Array(5).fill(null),free:result&&currentRecord.customTeam?currentRecord.customTeam.free:valid?saved.free:false,slot:0,page:0,query:'',standalone:!result};squadView();}
