function squadShow(saved){close();const team=saved.ids.map((id,slot)=>Object.assign({},person(id),{slot,isYou:false}));standaloneSquad={team,teamBrand:saved.teamBrand||E.makeSquadName(theme,team),custom:true};saved.teamBrand=standaloneSquad.teamBrand;write('squad.'+theme,saved);render(`<section class="result v12-result standalone-squad"><div class="result-top"><span>我的宇宙五人团 / 自选阵容</span><button class="text" data-action="home">返回宇宙大厅 ↗</button></div>${squadBrandPanel(standaloneSquad)}<p class="micro">这是你自选的五位队友，没有替你生成测试身份。想知道你是谁，可以另开一局。</p><div class="team-grid">${team.map(p=>`<article class="team-card" data-person="${p.id}" data-role="${p.slot}"><div class="team-role"><span>${themed().roles[p.slot]}</span><strong>TEAM / 0${p.slot+1}</strong></div><button class="team-portrait" data-action="person" data-id="${p.id}">${portrait(p)}</button><h3>${esc(p.nickname||p.name)}</h3><p>${esc(p.universe&&p.universe.teamHook||p.line)}</p></article>`).join('')}</div><div class="standalone-actions"><button class="secondary" data-action="squad-home">重新自选这五个人 ↗</button><button class="primary" data-action="start">再测测我是谁 ↗</button></div><div class="result-dock"><button class="primary" data-action="team-poster">生成这五个人的海报 ↗</button><button class="secondary" data-action="team-name">换个队名</button></div></section>`);}
function rerollSquadName(){const r=result||standaloneSquad;if(!r)return;const y=scrollY;r.teamBrand=E.makeSquadName(theme,r.team,r.teamBrand&&r.teamBrand.title||'');if(result){currentRecord.teamBrand=r.teamBrand;persistCurrentRecord();showResult(currentRecord);}else{const saved=read('squad.'+theme);if(saved){saved.teamBrand=r.teamBrand;squadShow(saved);}}requestAnimationFrame(()=>scrollTo(0,y));notify('新队名已抽中：'+r.teamBrand.title);}
function glow(ctx,x,y,r,c){const g=ctx.createRadialGradient(x,y,0,x,y,r);g.addColorStop(0,c);g.addColorStop(1,'rgba(0,0,0,0)');ctx.fillStyle=g;ctx.fillRect(x-r,y-r,r*2,r*2);}
