function action(e){const b=e.target.closest('[data-action]');if(!b||b.disabled)return;const a=b.dataset.action;
if(a==='team-name')rerollSquadName();else if(a==='team-poster')teamPoster();else if(a==='readthrough')readthrough();else if(a==='sample-chapter'){theme='lol';count=8;start('netcafe');}else if(a==='library-back')libraryBack();else if(a==='library-filter'){const v=library.stack[library.stack.length-1];v.filter=b.dataset.theme;v.owner='';v.scroll=0;libraryView();}else if(a==='intro')intro();else if(a==='intro-next'){if(introStep<2)intro(introStep+1);else{write('intro-seen',true);home();}}else if(a==='intro-prev')intro(introStep-1);else if(a==='intro-skip'){write('intro-seen',true);home();}else if(a==='reveal-open')showResult(currentRecord);else if(a==='home')home();else if(a==='theme'&&D.themes.some(t=>t.id===b.dataset.theme)){theme=b.dataset.theme;write('theme',theme);home();}else if(a==='mode'&&D.modes.includes(+b.dataset.count)){count=+b.dataset.count;write('count',count);home();}else if(a==='start')start();else if(a==='resume')resume();
else if(a==='answer'){if(advancing||!session)return;let step;try{step=E.recordAnswer(session,D,b.dataset.question,+b.dataset.id);}catch(_){return;}advancing=true;session=step.session;save();document.querySelectorAll('.option').forEach(el=>{el.disabled=true;el.setAttribute('aria-pressed',String(el===b));});const prev=$('[data-action=previous]');if(prev)prev.disabled=true;$('#answer-status').textContent='已选 '+b.querySelector('i').textContent+'，'+(step.complete?'正在揭晓你的平行身份…':'进入下一题…');const n=session.answers.filter(v=>v!==null).length;$('progress').value=n;answerTimer=setTimeout(()=>{answerTimer=null;if(step.complete)finish();else quiz();},180);}
else if(a==='previous'){if(advancing)return;if(session.index){session.index--;session.phase='quiz';save();quiz();}else home();}
else if(a==='squad')squadOpen();else if(a==='squad-home')squadOpen(true);else if(a==='squad-slot'){squadDraft.slot=+b.dataset.slot;squadDraft.page=0;squadView();}else if(a==='squad-pick'){const p=person(b.dataset.id),d=squadDraft;if(!p||p.theme!==theme||(!d.free&&!p.roles.includes(d.slot))||d.ids.some((id,i)=>i!==d.slot&&id===p.id))return;d.ids[d.slot]=p.id;d.query='';d.page=0;const empty=d.ids.findIndex(id=>!id);if(empty>=0)d.slot=empty;squadView();}else if(a==='squad-free'){squadDraft.free=!squadDraft.free;squadDraft.page=0;squadView();}else if(a==='squad-remove'){squadDraft.ids[squadDraft.slot]=null;squadView();}else if(a==='squad-fill'){try{squadDraft.ids=E.fillSquad(squadDraft.ids,theme,D,result?result.vector:Array(6).fill(50),squadDraft.free);squadView();}catch(e){notify(e.message);}}else if(a==='squad-page'){squadDraft.page=Math.max(0,squadDraft.page+(+b.dataset.delta));squadView();}else if(a==='squad-load'){const v=read('squad.'+theme);if(v&&!E.squadError(v.ids,theme,D,v.free)){squadDraft.ids=v.ids.slice();squadDraft.free=v.free;squadView();}}else if(a==='squad-save')squadSave();else if(a==='auto-team'){delete currentRecord.customTeam;write('history',[currentRecord,...history().filter(r=>r.id!==currentRecord.id)].slice(0,12));showResult(currentRecord);}else if(a==='gallery-page'){listPage+=+b.dataset.delta;gallery(false);}else if(a==='card-page'){listPage+=+b.dataset.delta;cardGallery(false);}else if(a==='meme')showMeme(b.dataset.id);else if(a==='meme-start'){const m=D.memeReferences.find(m=>m.id===b.dataset.id);if(m)start(m.chapter,m.series);}else if(a==='person')showPerson(b.dataset.id);else if(a==='gallery')gallery();else if(a==='story-preview')storyPreview();else if(a==='archive')archive();else if(a==='history'){const r=history()[+b.dataset.index];if(r)showResult(r);}else if(a==='review')review();else if(a==='alternatives')alternatives();else if(a==='card-note')cardNote(b.dataset.id);else if(a==='peek')peek(b.dataset.id);else if(a==='card-gallery')cardGallery();else if(a==='sample')sample(b.dataset.behavior);else if(a==='poster')poster();else if(a==='download-html')downloadHTML();else if(a==='about')about();else if(a==='trend-note')trendNote();
else if(a==='palette'){const s=document.documentElement.dataset.style==='paper'?'night':'paper';document.documentElement.dataset.style=s;write('style',s);write('style.v12',s);paletteLabel();}
else if(a==='clear')open('清除本机 本机记录？','<p>将清除本版答题进度与历史。</p><button class="primary" data-action="clear-confirm">清除本版记录</button>');else if(a==='clear-confirm'){remove('session');remove('history');session=null;result=null;home();notify('本机进度和档案已清除');}}
